<?php

namespace Dsl\App\Entities;

use Dsl\App\Form\DynFormTable;
use Dsl\App\MemberShip;
use Dsl\App\Navigation;
use Dsl\App\Page;
use JetBrains\PhpStorm\ArrayShape;

class FachPlanung
{
    /**
     * @param DienstStelle $dienstStelle Dienststelle der Fachplanung
     * @param GesamtPlan $gesamtPlan Gesamtplan zu welcher die Fachplanung gehört
