     * @param bool $geschlossen Ist der Fachplanung abgeschlossen
     * @param string $nameDienstStelleHistorisch Name der Dienststelle während der Erstellung der Fachplanung (Bitte bei Ausgabe verwenden)
     */
    protected function __construct(
        public DienstStelle $dienstStelle,
        public GesamtPlan $gesamtPlan,
        public int $redakteurLevel,
        public bool $geschlossen,
        public string $nameDienstStelleHistorisch,
        public $massnahmen = null
    ) {
    }

    /**
     * Gibt eine Fachplanung einer Dienststelle bezüglich eines Gesamtplans zurück, null wenn nicht vorhanden
     * @param DienstStelle $dienstStelle Dienststelle der Fachplanung
     * @param GesamtPlan $gesamtPlan Gesamtplan der Dienststelle
     * @return FachPlanung|null null = Fachplanung nicht vorhanden
     */
    public static function getFachPlanung(DienstStelle $dienstStelle, GesamtPlan $gesamtPlan): ?FachPlanung
    {
        $sql = "SELECT name_dienststelle_historisch, redakteur_level, geschlossen FROM fachplanung
                WHERE fk_gesamtplan = {$gesamtPlan->jahr} AND fk_dienststelle = '{$dienstStelle->nummer}'";
        $row = Page::db()->querySingleRow($sql);
        if ($row) {
            return new FachPlanung(
                $dienstStelle,
                $gesamtPlan,
                (int)$row['redakteur_level'],
                ((int)$row['geschlossen']) === 1,
                $row['name_dienststelle_historisch']
            );
        } else {
            return null;
        }
    }

    /**
     * Gibt alle Fachplanungen eines GesamtPlans zurück.
     * @param GesamtPlan $gesamtPlan Gesamtplan
     * @param bool $nurRessort true = nur Ressort, false = auch untergeordnete DienstStellen
     * @param bool|null $active true = nur aktive Dienststellen, false = nur inaktive Dienststellen, null = alle Dienststellen
     * @return FachPlanung[]
     */
    public static function getGesamtPlanFachPlanungen(GesamtPlan $gesamtPlan, bool $nurRessort = false, ?bool $active = null): array
